        int alpha_channel = strcmp(imOut->mode, "RGBa") == 0 ||
                            strcmp(imOut->mode, "RGBA") == 0 ||
                            strcmp(imOut->mode, "La") == 0 ||
                            strcmp(imOut->mode, "LA") == 0 ||
